#!/usr/bin/env bash
# Nettoyage : 40 fichiers, 33 procédures et 10 exports que plus rien n'appelle (liste et preuves dans le message de commit).
# Prérequis : apply-docs-garde-prod.sh. Aucune migration.
# Usage (racine du repo) : bash apply-fix-nettoyage.sh
set -euo pipefail
cd "$(dirname "$0")"
